const mode=new URLSearchParams(location.search).get('demo')||'operations', app=document.getElementById('app');
const orders=[['1048','River Foods','In transit','£4,820','18 Oct'],['1047','Corner Market','Review','£2,140','19 Oct'],['1046','Westside Supply','Delivered','£7,460','20 Oct'],['1045','Greenway Co.','Review','£1,280','21 Oct']];
const cases=[['Amina Yusuf','Delivery missing','Open','2h ago'],['Joel Mensah','Invoice correction','Open','4h ago'],['River Foods','Contract renewal','Waiting','Yesterday']];
function operations(){app.innerHTML=`<div class="ops"><header><b>◈ &nbsp; Northline</b><span>Operations / Orders</span><span>Search &nbsp; ⌕ &nbsp; ○</span></header><div class="opsbody"><aside><b>WORKSPACE</b><p>Overview</p><p class="current">Orders</p><p>Partners</p><p>Inventory</p><p>Reports</p></aside><section><div class="path">Operations / Orders</div><div class="opstitle"><div><h1>Orders</h1><p>Manage deliveries and exceptions</p></div><button type="button" id="filter">Show review only</button></div><div class="toolbar"><b id="order-count">Orders (4)</b><span>Order ID &nbsp; Partner &nbsp; Status</span></div><div class="table"><div class="tablehead"><span>ORDER</span><span>PARTNER</span><span>STATUS</span><span>VALUE</span><span>DUE</span></div><div id="rows"></div></div><div id="order-detail" class="detail">Select an order to view its details.</div></section></div></div>`;let review=false;function render(){let items=orders.filter(x=>!review||x[2]==='Review');document.getElementById('order-count').textContent=`Orders (${items.length})`;document.getElementById('rows').innerHTML=items.map(x=>`<button class="order-row" data-id="${x[0]}"><span>#${x[0]}</span><span>${x[1]}</span><span><i class="dot"></i>${x[2]}</span><span>${x[3]}</span><span>${x[4]}</span></button>`).join('');document.querySelectorAll('.order-row').forEach(b=>b.onclick=()=>{let o=orders.find(x=>x[0]===b.dataset.id);document.getElementById('order-detail').textContent=`Order #${o[0]} · ${o[1]} · ${o[2]} · ${o[3]} · Due ${o[4]}`})}document.getElementById('filter').onclick=e=>{review=!review;e.currentTarget.textContent=review?'Show all orders':'Show review only';document.getElementById('order-detail').textContent='Select an order to view its details.';render()};render()}
function casework(){app.innerHTML=`<div class="case"><header><strong>FIELDNOTE</strong><span>Cases &nbsp; / &nbsp; Inbox</span><span>Team workspace &nbsp; ◉</span></header><div class="casebody"><aside><h1>Inbox <small>3</small></h1><p>Assigned to you</p><div class="case-list">${cases.map((x,i)=>`<button class="case-item ${i===0?'selected':''}" data-case="${i}"><b>${x[0]}</b><small>${x[1]}</small><em>${x[3]} · ${x[2]}</em></button>`).join('')}</div></aside><section><div class="case-top"><span>CASE <b id="case-id">#201</b></span><span class="tag" id="case-status">OPEN</span></div><h1 id="case-title">Delivery missing</h1><p id="case-person">Amina Yusuf · Corner Market</p><div class="case-tabs">Conversation <span>Details</span> <span>Activity</span></div><div class="message"><b id="message-person">Amina Yusuf</b><small id="message-time">Today at 09:15</small><p id="message-text">The water was delivered, but the juice was missing. Can you check the order?</p></div><div class="message reply"><b>Jordan Lee</b><small id="reply-time">Today at 10:02</small><p id="reply-text">Thanks, I’ll check with the delivery team and update you.</p></div><div class="reply-box">Assigned to Jordan Lee</div></section><aside class="case-context"><b>CASE DETAILS</b><p>Owner<br><strong>Jordan Lee</strong></p><p>Priority<br><strong>Normal</strong></p><p>Next step<br><strong id="next-step">Check delivery record</strong></p><p>Related record<br><strong id="related-record">#1048</strong></p></aside></div></div>`;document.querySelectorAll('[data-case]').forEach(b=>b.onclick=()=>{let i=+b.dataset.case,c=cases[i];document.querySelectorAll('[data-case]').forEach(x=>x.classList.toggle('selected',x===b));document.getElementById('case-id').textContent='#'+(201+i);document.getElementById('case-title').textContent=c[1];document.getElementById('case-person').textContent=c[0]+' · Partner';document.getElementById('message-time').textContent=['Today at 09:15','Today at 07:15','Yesterday at 14:10'][i];document.getElementById('reply-time').textContent=['Today at 10:02','Today at 08:10','Yesterday at 15:20'][i];document.getElementById('case-status').textContent=c[2].toUpperCase();document.getElementById('next-step').textContent=['Check delivery record','Review invoice','Review terms'][i];document.getElementById('related-record').textContent=['Order #1048','Invoice #821','Agreement #302'][i];document.getElementById('reply-text').textContent=['Thanks, I’ll check with the delivery team and update you.','I’ll compare the invoice with the agreed amount.','I’ll review the agreement and follow up.'][i];document.getElementById('message-person').textContent=c[0];document.getElementById('message-text').textContent=['The water was delivered, but the juice was missing. Can you check the order?','The invoice total differs from the agreed amount. Can you review it?','Can we review the renewal terms before the end of the month?'][i]})}
function board(){app.innerHTML=`<div class="board"><header><strong>▧ &nbsp; TERN</strong><span>Projects &nbsp; / &nbsp; Partner rollout</span><span>⌕ &nbsp; ○ JL</span></header><div class="boardbody"><div class="boardtitle"><div><small>PROJECT / OPERATIONS</small><h1>Partner rollout</h1><p>Coordinate onboarding across the team.</p></div><div class="members">AL &nbsp; KM &nbsp; JL</div></div><div class="boardtabs"><b>Board</b><span>List</span><span>Timeline</span><span>Files</span></div><div class="columns"><div><h3>To do <span id="todo-count">2</span></h3><div class="task"><small>ONBOARDING</small><b>Confirm delivery zones</b><p>Assign regional coverage</p><footer>AL <span>21 Oct</span></footer></div><div class="task"><small>OPERATIONS</small><b>Prepare partner pack</b><p>Terms and contact details</p><footer>KM <span>23 Oct</span></footer></div></div><div><h3>In progress <span id="doing-count">2</span></h3><div class="task"><small>FINANCE</small><b>Verify payment details</b><p>3 of 5 partners reviewed</p><footer>JL <span>19 Oct</span></footer></div><div class="task" id="movable"><small>COMPLIANCE</small><b>Review supply agreement</b><p>Waiting for final terms</p><footer>AL <button id="move-task">Mark done →</button></footer></div></div><div><h3>Done <span id="done-count">1</span></h3><div id="done"><div class="task"><small>RESEARCH</small><b>Map partner requirements</b><p>Notes shared with team</p><footer>KM <span>14 Oct</span></footer></div></div></div></div></div></div>`;document.getElementById('move-task').onclick=()=>{document.querySelector('#movable p').textContent='Agreement reviewed';document.getElementById('done').append(document.getElementById('movable'));document.getElementById('move-task').remove();document.getElementById('doing-count').textContent='1';document.getElementById('done-count').textContent='2'}}
function report(){app.innerHTML=`<div class="report"><header><b>HARBOR <span> / </span> INSIGHTS</b><span>Reports &nbsp;&nbsp; Portfolio &nbsp;&nbsp; Research</span><span>JL &nbsp; ○</span></header><div class="reportbody"><div class="reportbar"><span>MONTHLY REVIEW &nbsp; / &nbsp; 2026</span><span>October 2026</span></div><div class="reportgrid"><section><div class="issue">OPERATIONS BRIEF &nbsp; — &nbsp; 01</div><h1 id="report-title">A stronger month<br>for delivery.</h1><p id="report-summary">On-time delivery improved as the northern region cleared its backlog.</p><div class="bigmetric"><span>On-time delivery</span><strong id="rate">96.4<small>%</small></strong><em id="change">↑ 1.2 points from September</em></div><div class="trend"><span>DELIVERY PERFORMANCE</span><div class="bars"><i style="height:50%"></i><i style="height:67%"></i><i style="height:58%"></i><i style="height:80%"></i><i style="height:72%"></i><i style="height:90%"></i></div><small>May &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Jun &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Jul &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Aug &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Sep &nbsp;&nbsp;&nbsp;&nbsp;&nbsp; Oct</small></div></section><aside><b>IN THIS REPORT</b><div><small>01 / PERFORMANCE</small><h3>Delivery improved</h3><p>Four of five regions met the 95% target.</p></div><div><small>02 / ATTENTION</small><h3>South region</h3><p>Late supplier dispatch affected 12 orders.</p></div><div><small>03 / NEXT STEP</small><h3>Review capacity</h3><p>Confirm cover for the November peak.</p></div></aside></div></div></div>`}
function humanizer(){app.innerHTML=`<div class="humanizer"><header><b>HUMANIZER / WRITING SKILL</b><span>Product copy example</span></header><section><div class="human-label">BEFORE <span>01</span></div><blockquote>This powerful workspace seamlessly brings orders, conversations and agreements together, empowering your team to stay aligned and unlock new possibilities.</blockquote><div class="human-rule">↓ &nbsp; State what the reader can do</div><div class="human-label">AFTER <span>02</span></div><blockquote class="human-after">See orders, conversations and agreements in one workspace.</blockquote><p>This is a fixed illustration, not an automatic rewrite.</p></section></div>`}
function fonts(){const names=['IBM Plex Sans','Source Sans 3','Work Sans','DM Sans','Manrope','Source Serif 4','IBM Plex Serif'];app.innerHTML=`<div class="fonts"><header><b>TYPE / REFERENCE</b><span>Choose a font to compare</span></header><div class="font-body"><aside>${names.map((n,i)=>`<button data-font="${n}" class="${i===0?'selected':''}">${n}</button>`).join('')}</aside><section><small>INTERFACE TYPE SPECIMEN</small><h1 id="font-name">IBM Plex Sans</h1><p class="font-large">Clear information for the work ahead.</p><div class="font-samples"><p><b>Orders to review</b><br>Review the delivery date and confirm the order details.</p><p><b>12,480</b><br>0123456789 £ € $ &amp; %</p></div><div class="font-label">Headings, body text and numerals</div></section></div></div>`;document.querySelectorAll('[data-font]').forEach(b=>b.onclick=()=>{document.querySelectorAll('[data-font]').forEach(x=>x.classList.toggle('selected',x===b));document.querySelector('.font-body section').style.fontFamily=`'${b.dataset.font}',sans-serif`;document.getElementById('font-name').textContent=b.dataset.font})}({operations,casework,board,report,fonts,humanizer}[mode]||operations)();
